CREATE SCHEMA IF NOT EXISTS quality_ops;
CREATE TABLE quality_ops.test_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),suite text NOT NULL CHECK(suite IN('e2e','api','accessibility','visual','browser','mobile')),revision char(40) NOT NULL CHECK(revision~'^[a-f0-9]{40}$'),environment text NOT NULL CHECK(environment IN('ci','staging')),status text NOT NULL CHECK(status IN('queued','running','passed','failed','cancelled')),browsers jsonb NOT NULL DEFAULT '[]',tests_total integer NOT NULL DEFAULT 0 CHECK(tests_total>=0),tests_passed integer NOT NULL DEFAULT 0 CHECK(tests_passed>=0),tests_failed integer NOT NULL DEFAULT 0 CHECK(tests_failed>=0),requested_by uuid NOT NULL,started_at timestamptz,finished_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(tests_passed+tests_failed<=tests_total));
CREATE INDEX quality_test_runs_recent_idx ON quality_ops.test_runs(tenant_id,created_at DESC);
CREATE TABLE quality_ops.test_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),run_id uuid NOT NULL REFERENCES quality_ops.test_runs(id) ON DELETE CASCADE,test_key varchar(180) NOT NULL,browser varchar(40) NOT NULL,status text NOT NULL CHECK(status IN('passed','failed','skipped','quarantined')),duration_ms integer NOT NULL CHECK(duration_ms>=0),attempt smallint NOT NULL DEFAULT 1 CHECK(attempt BETWEEN 1 AND 10),error_code varchar(120),artifact_key text,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(run_id,test_key,browser,attempt));
CREATE TABLE quality_ops.accessibility_findings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),run_id uuid NOT NULL REFERENCES quality_ops.test_runs(id) ON DELETE CASCADE,rule_id varchar(120) NOT NULL,impact text NOT NULL CHECK(impact IN('critical','serious','moderate','minor')),impact_rank smallint NOT NULL CHECK(impact_rank BETWEEN 1 AND 4),route varchar(240) NOT NULL,browser varchar(40) NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','accepted','resolved')),selector_hash varchar(64) NOT NULL,detected_at timestamptz NOT NULL DEFAULT clock_timestamp(),resolved_at timestamptz);
CREATE INDEX quality_a11y_open_idx ON quality_ops.accessibility_findings(tenant_id,status,impact_rank DESC) WHERE status<>'resolved';
CREATE TABLE quality_ops.visual_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),run_id uuid NOT NULL REFERENCES quality_ops.test_runs(id) ON DELETE CASCADE,snapshot_key varchar(180) NOT NULL,browser varchar(40) NOT NULL,viewport varchar(40) NOT NULL,baseline_hash varchar(64) NOT NULL,current_hash varchar(64) NOT NULL,changed_pixels integer NOT NULL DEFAULT 0 CHECK(changed_pixels>=0),total_pixels integer NOT NULL CHECK(total_pixels>0),status text NOT NULL CHECK(status IN('matched','changed','approved')),approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(run_id,snapshot_key,browser,viewport));
CREATE TABLE quality_ops.release_gates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),revision char(40) NOT NULL,environment text NOT NULL CHECK(environment IN('ci','staging','production')),decision text NOT NULL CHECK(decision IN('allow','block')),reasons jsonb NOT NULL DEFAULT '[]',evidence_hash varchar(64) NOT NULL CHECK(evidence_hash~'^[a-f0-9]{64}$'),decided_by uuid NOT NULL,decided_at timestamptz NOT NULL DEFAULT clock_timestamp(),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,revision,environment));
CREATE TABLE quality_ops.daily_metrics(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),metric_date date NOT NULL,total_runs integer NOT NULL DEFAULT 0,passed_runs integer NOT NULL DEFAULT 0,failed_runs integer NOT NULL DEFAULT 0,pass_rate_bps integer NOT NULL DEFAULT 0 CHECK(pass_rate_bps BETWEEN 0 AND 10000),critical_defects integer NOT NULL DEFAULT 0,serious_a11y integer NOT NULL DEFAULT 0,flaky_tests integer NOT NULL DEFAULT 0,browser_coverage_bps integer NOT NULL DEFAULT 0 CHECK(browser_coverage_bps BETWEEN 0 AND 10000),last_run_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,metric_date));
CREATE OR REPLACE FUNCTION quality_ops.prevent_gate_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'quality gate evidence is append-only';END$$;
CREATE TRIGGER quality_gate_append_only BEFORE UPDATE OR DELETE ON quality_ops.release_gates FOR EACH ROW EXECUTE FUNCTION quality_ops.prevent_gate_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['test_runs','test_results','accessibility_findings','visual_snapshots','release_gates','daily_metrics'] LOOP EXECUTE format('ALTER TABLE quality_ops.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE quality_ops.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation_quality_%I ON quality_ops.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
